//! The Meshtastic protobufs, generated by prost from the files vendored under
//! `protobufs/`, and the framing the client API wraps them in over a stream.
//!
//! Which upstream revision the protobufs are is in `protobufs/UPSTREAM_REV`,
//! and `scripts/update-protobufs.sh` is how they get replaced.

pub mod frame;

/// Everything in the `meshtastic` protobuf package.
#[allow(clippy::all, clippy::pedantic, missing_docs)]
pub mod meshtastic {
    include!(concat!(env!("OUT_DIR"), "/meshtastic.rs"));
}

#[cfg(test)]
mod tests {
    use super::meshtastic::{FromRadio, MyNodeInfo, ToRadio, from_radio, to_radio};
    use prost::Message;

    #[test]
    fn a_config_request_survives_the_round_trip() {
        let request = ToRadio {
            payload_variant: Some(to_radio::PayloadVariant::WantConfigId(42)),
        };
        let decoded = ToRadio::decode(request.encode_to_vec().as_slice()).unwrap();
        assert_eq!(decoded, request);
    }

    #[test]
    fn the_radio_says_who_it_is() {
        let answer = FromRadio {
            id: 1,
            payload_variant: Some(from_radio::PayloadVariant::MyInfo(MyNodeInfo {
                my_node_num: 0x1234_5678,
                ..Default::default()
            })),
        };
        let decoded = FromRadio::decode(answer.encode_to_vec().as_slice()).unwrap();
        assert_eq!(decoded, answer);
    }
}
